// BACKEND DUMMY andon untuk tablet. State di memori global Node-RED (hilang saat Node-RED restart).
// ponytail: data dummy dalam kode. Ganti ke database/API asli kalau sudah ada.
const STATIONS = [
  ['MA-1-LH', 'Main Assy-1-LH'], ['MA-1-RH', 'Main Assy-1-RH'], ['MA-3-LH', 'Main Assy-3-LH'],
  ['MA-3-RH', 'Main Assy-3-RH'], ['MA-5-LH', 'Main Assy-5-LH'], ['MA-5-RH', 'Main Assy-5-RH'],
  ['MA-6-LH', 'Main Assy-6-LH'], ['MA-7-RH', 'Main Assy-7-RH'], ['MA-8-LH', 'Main Assy-8-LH'],
  ['MA-8-RH', 'Main Assy-8-RH'], ['MA-9-RH', 'Main Assy-9-RH'], ['MA-10-LH', 'Main Assy-10-LH'],
  ['MA-11-LH', 'Main Assy-11-LH'], ['MA-11-RH', 'Main Assy-11-RH'], ['MA-12-LH', 'Main Assy-12-LH'],
  ['MA-13-RH', 'Main Assy-13-RH'], ['MA-14-LH', 'Main Assy-14-LH'], ['MA-15-RH', 'Main Assy-15-RH'],
  ['MA-16-LH', 'Main Assy-16-LH']
].map(([code, name]) => ({ code, name }));

const CATALOG = [
  { key: 'quality', name: 'Quality', reasons: ['Part NG / reject', 'Dimensi di luar toleransi', 'Cacat visual', 'Torque tidak sesuai'] },
  { key: 'logistic', name: 'Logistic', reasons: ['Part habis', 'Part salah kirim', 'Part terlambat', 'Trolley kosong'] },
  { key: 'equipment', name: 'Equipment', reasons: ['Mesin berhenti', 'Tool rusak', 'Sensor error', 'Tekanan angin turun'] },
  { key: 'process', name: 'Process', reasons: ['Operator kurang', 'Cycle time terlalu lama', 'Instruksi kerja tidak jelas', 'Setting ulang proses'] }
];

const ACCOUNTS = [
  { email: 'operator1@dummy.local', password: 'operator1', name: 'Operator Satu' },
  { email: 'operator2@dummy.local', password: 'operator2', name: 'Operator Dua' }
];

const path = '/andon/' + msg.req.params.action;
const body = (msg.payload && typeof msg.payload === 'object') ? msg.payload : {};
const reply = (code, payload) => { msg.statusCode = code; msg.payload = payload; return [msg, null]; };

if (path === '/andon/stations') return reply(200, STATIONS);

if (path === '/andon/login') {
  const ok = typeof body.email === 'string' && typeof body.password === 'string';
  const acc = ok && ACCOUNTS.find(a => a.email === body.email.trim().toLowerCase() && a.password === body.password);
  if (!acc) return reply(401, { message: 'Incorrect email or password.' });
  // ponytail: token acak seadanya (dummy). Ganti JWT/sesi asli saat login sungguhan.
  const token = Date.now().toString(36) + Math.random().toString(36).slice(2) + Math.random().toString(36).slice(2);
  const tokens = global.get('andonTokens') || {};
  tokens[token] = { email: acc.email, name: acc.name };
  global.set('andonTokens', tokens);
  // sesi operator -> tabel "Duty Worker" di dashboard. Login baru di station yang sama menutup sesi lama.
  const station = STATIONS.some(s => s.code === body.station) ? body.station : '-';
  const t = Date.now();
  const sessions = global.get('andonSessions') || [];
  sessions.forEach(x => { if (!x.end && station !== '-' && x.station === station) x.end = t; });
  sessions.push({ token, name: acc.name, station, start: t, end: null });
  global.set('andonSessions', sessions.slice(-60));
  return reply(200, { token, name: acc.name });
}

// semua di bawah ini wajib login
const bearer = String(msg.req.headers.authorization || '').replace(/^Bearer /, '');
const user = (global.get('andonTokens') || {})[bearer];
if (!user) return reply(401, { message: 'Unauthorized' });

if (path === '/andon/catalog') return reply(200, CATALOG);

if (path === '/andon/logout') {
  const t = Date.now();
  const sessions = global.get('andonSessions') || [];
  sessions.forEach(x => { if (x.token === bearer && !x.end) x.end = t; });
  global.set('andonSessions', sessions);
  const tokens = global.get('andonTokens') || {};
  delete tokens[bearer];
  global.set('andonTokens', tokens);
  return reply(200, { ok: true });
}

const station = String(path === '/andon/state' ? (msg.req.query.station || '') : (body.station || ''));
if (!STATIONS.some(s => s.code === station)) return reply(400, { message: 'Station tidak dikenal' });

const now = Date.now();
const events = (global.get('andonEvents') || []).filter(e => !e.end || now - e.start < 48 * 3600e3);
const active = events.find(e => !e.end && e.station === station);

if (path === '/andon/start') {
  const cat = CATALOG.find(c => c.key === body.category);
  if (!cat || !cat.reasons.includes(body.reason)) return reply(400, { message: 'Kategori atau alasan tidak valid' });
  if (active) return reply(409, { message: 'Andon masih aktif di station ini. Stop dulu.' });
  events.push({ station, category: cat.key, reason: body.reason, operator: user.name, start: now, end: null });
} else if (path === '/andon/stop') {
  if (!active) return reply(409, { message: 'Tidak ada andon aktif di station ini.' });
  active.end = now;
  active.stoppedBy = user.name;
}

global.set('andonEvents', events);
msg.station = station;
return [null, msg];   // lanjut ke "ringkasan" untuk balasan + siaran dashboard

// Hitung ringkasan andon per kategori (seluruh line, hari ini WIB).
// Dipanggil: tiap 1 detik (siaran dashboard), dan setelah state/start/stop dari tablet (balasan HTTP + siaran).
const SEC_PER_MIN = 60;   // dummy cepat: ubah ke 5 supaya menit cepat berubah saat uji
const CATS = ['quality', 'logistic', 'equipment', 'process'];
const now = Date.now();

// Riwayat awal supaya dashboard tidak kosong saat pameran (menit lalu, durasi menit, kategori, alasan, station).
// Ini event andon sungguhan di memori; hapus blok ini bila tidak mau data awal.
if (!global.get('andonSeeded')) {
  global.set('andonSeeded', true);
  const M = 60e3;
  const ev0 = [
    [470, 3, 'equipment', 'Sensor error', 'MA-5-LH'], [395, 5, 'logistic', 'Part habis', 'MA-1-RH'],
    [330, 2, 'quality', 'Part NG / reject', 'MA-3-LH'], [262, 4, 'process', 'Cycle time terlalu lama', 'MA-8-RH'],
    [190, 3, 'logistic', 'Trolley kosong', 'MA-11-LH'], [128, 6, 'equipment', 'Tool rusak', 'MA-6-LH'],
    [95, 2, 'quality', 'Cacat visual', 'MA-3-RH'], [41, 3, 'process', 'Operator kurang', 'MA-12-LH'],
    [17, 2, 'quality', 'Torque tidak sesuai', 'MA-14-LH']
  ].map(([ago, dur, category, reason, station]) => ({ station, category, reason, operator: 'Operator Satu', start: now - ago * M, end: now - (ago - dur) * M }));
  global.set('andonEvents', [...(global.get('andonEvents') || []), ...ev0]);
  global.set('andonSessions', [
    ['Denny', 'MA-1-RH', 400, 330], ['Rijal', 'MA-16-LH', 330, 250], ['Idris', 'MA-9-RH', 250, 180],
    ['Fadillah', 'MA-11-LH', 200, 120], ['Rijal', 'MA-6-LH', 150, 70], ['Moh Wisnu', 'MA-5-LH', 55, null]
  ].map(([name, station, a, b]) => ({ name, station, start: now - a * M, end: b === null ? null : now - b * M })));
}

const day = t => new Date(t + 7 * 3600e3).toISOString().slice(0, 10);   // tanggal WIB
const today = day(now);
const events = global.get('andonEvents') || [];

const dt = {}, secs = {}, running = {};
for (const c of CATS) { dt[c] = { active: false, count: 0, minutes: 0, station: '-' }; secs[c] = 0; running[c] = []; }

for (const e of events) {
  if (e.end && day(e.start) !== today) continue;   // selesai di hari lain: abaikan (andon aktif lintas hari tetap dihitung)
  dt[e.category].count++;
  secs[e.category] += ((e.end || now) - e.start) / 1000;   // aktif: lama berjalan ikut dihitung
  if (!e.end) running[e.category].push(e);
}
for (const c of CATS) {
  dt[c].minutes = Math.floor(secs[c] / SEC_PER_MIN);
  const r = running[c].sort((a, b) => a.start - b.start);
  if (r.length) {
    dt[c].active = true;
    dt[c].station = r[0].station + (r.length > 1 ? ' +' + (r.length - 1) : '');
  }
}

// ponytail: 6 angka non-andon ini konstan (dummy). Ganti saat ada sumber data produksi.
// events + workers = data mentah untuk halaman /line (analitik dihitung di frontend).
const cut = now - 24 * 3600e3;
const evOut = events.filter(e => (e.end || now) > cut).map(({ station, category, reason, operator, start, end }) => ({ station, category, reason, operator, start, end }));
const workers = (global.get('andonSessions') || []).slice(-40).map(({ name, station, start, end }) => ({ name, station, start, end }));
const dashboard = { target: 92, assyOut: 55, efficiency: 90, jph: 12, ct: 5, handover: 34, downtime: dt, now, events: evOut, workers, ts: new Date(now).toISOString() };

const toDashboard = { payload: dashboard };   // tanpa req/res: disiarkan ke semua dashboard
if (!msg.res) return [null, toDashboard];     // dari timer

const a = events.find(e => !e.end && e.station === msg.station);
msg.payload = {
  active: a ? { category: a.category, reason: a.reason, start: a.start, operator: a.operator } : null,
  downtime: dt,
  now
};
return [msg, toDashboard];

// BACKEND DUMMY tablet QC + siaran ke dashboard (/ws/qc). State di memori global Node-RED (hilang saat restart).
// Terpisah dari andon. Satu function untuk semua: HTTP /qc/:action dan timer 1 detik.
// ponytail: data dummy dalam kode. Ganti ke database/API asli kalau sudah ada.
const STATION = 'Fit Finish';
const OPERATOR = 'Operator QC';
const SESSION_MS = 15 * 60e3;   // sesi diam > 15 menit dilepas otomatis
const M = 60e3;

const ALL = ['Misassembled', 'Missing Part', 'Over cutting', 'Peel-Off', 'Poor Repair', 'Scratch', 'Stain', 'Tear', 'Touch Mark', 'Wrong Position', 'Wrong specification'];
const GEN = ['Misassembled', 'Missing Part', 'Scratch', 'Stain', 'Touch Mark', 'Wrong Position'];
// [id, nama, berkas foto di tablet QC/public/parts/<x>.png (kosong = ikon), defect khusus + umum]
const PARTS = [
  ['p1', 'Body Cover RH', 'body-cover-rh', ['Gap-Above', ...ALL]],
  ['p2', 'Body Cover LH', 'body-cover-lh', ['Gap-Above', ...ALL]],
  ['p3', 'Rear Mud Guard', 'rear-mud-guard', ['Misalignment', ...GEN]],
  ['p4', 'Speedometer', 'speedometer', ['Gate Blush', ...GEN]],
  ['p5', 'Steering Cover Rear', 'steering-cover-rear', ['Touching', ...GEN]],
  ['p6', 'Rear Handle RH', 'rear-handle-rh', ['Damage', ...GEN]],
  ['p7', 'Keyless SET', 'keyless-set', ['Gap-Above', 'Flush', ...GEN]],
  ['p8', 'Foot Step LH', 'foot-step-lh', ['Touching', ...GEN]],
  ['p9', 'Foot Step RH', 'foot-step-rh', ['Abnormal Function', ...GEN]],
  ['p10', 'Horn', '', ['Abnormal Sound', ...GEN]]
].map(([id, name, image, d], i) => ({ id, no: i + 1, name, image, defects: [...new Set(d)].sort() }));
const PN = Object.fromEntries(PARTS.map(p => [p.id, p.name]));

// VIN dummy: VINALVA + 11 digit, nomor 1..99 valid. Model bergilir. 004 sudah selesai, 005 sedang dikerjakan, 006 menunggu repair.
const MODELS = ['Alva N3 Basic LFP 2026 1Batt B2B Grab White', 'Alva N3 Plus LFP 2026 2Batt Matte Black', 'Alva CervoX LFP 2026 1Batt Shadow Black'];
const unitOf = vin => {
  const m = /^VINALVA(\d{11})$/.exec(vin);
  const n = m ? parseInt(m[1], 10) : 0;
  return n >= 1 && n <= 99 ? { vin, model: MODELS[(n - 1) % 3], family: (n - 1) % 3 === 2 ? 'CERVO' : 'N3' } : null;
};

// Data awal supaya dashboard tidak kosong: 70 inspeksi 9 jam terakhir (30 NG, 40 GOOD). VIN riwayat (nomor > 99) tidak bisa di-scan.
const fresh = now => {
  const w = [['p3', 'Misalignment', 14], ['p4', 'Gate Blush', 11], ['p5', 'Touching', 9], ['p1', 'Gap-Above', 8], ['p6', 'Damage', 7],
    ['p2', 'Gap-Above', 6], ['p7', 'Gap-Above', 5], ['p8', 'Touching', 4], ['p7', 'Flush', 3], ['p9', 'Abnormal Function', 2]];
  const flat = [];
  w.forEach(([partId, defect, c]) => { for (let i = 0; i < c; i++) flat.push({ partId, defect }); });
  const results = [];
  let k = 0;
  for (let i = 0; i < 70; i++) {
    const bad = i % 7 < 3;
    const ng = bad ? flat.filter((_, j) => j % 30 === k) : [];
    if (bad) k++;
    results.push({ id: 's' + i, vin: 'VINALVA' + String(100 + i).padStart(11, '0'), model: MODELS[i % 3], at: now - (i + 1) * 8 * M,
      operator: OPERATOR, status: bad ? 'NOT_GOOD' : 'GOOD', ng, seconds: 40 + (i * 7) % 50 });
  }
  return {
    units: { VINALVA00000000004: 'finalized', VINALVA00000000006: 'repair' },
    sessions: [{ vin: 'VINALVA00000000005', deviceId: 'seed', operator: 'Operator QC 2', start: now, sticky: true }],
    results
  };
};

const now = Date.now();
let S = global.get('qc');
if (!S) S = fresh(now);
S.sessions = S.sessions.filter(s => s.sticky || now - s.start < SESSION_MS);

const summary = () => {
  const rs = S.results.filter(r => r.at >= now - 24 * 3600e3);
  const good = rs.filter(r => r.status === 'GOOD').length;
  const cnt = new Map();
  for (const r of rs) for (const g of r.ng) { const k = g.partId + '|' + g.defect; cnt.set(k, (cnt.get(k) || 0) + 1); }
  const top = [...cnt].map(([k, count]) => { const [partId, defect] = k.split('|'); return { partId, part: PN[partId], defect, count }; })
    .sort((a, b) => b.count - a.count || a.part.localeCompare(b.part)).slice(0, 10);
  return {
    station: STATION,
    totals: { inspected: rs.length, good, notGood: rs.length - good, okRate: rs.length ? Math.round(good / rs.length * 1000) / 10 : 0 },
    top,
    byPart: PARTS.map(p => ({ partId: p.id, part: p.name, count: rs.reduce((n, r) => n + r.ng.filter(g => g.partId === p.id).length, 0) })),
    active: S.sessions.map(s => ({ vin: s.vin, operator: s.operator, since: s.start })),
    recent: rs.slice(0, 10).map(r => ({ vin: r.vin, model: r.model, at: r.at, status: r.status, ng: r.ng.length })),
    now, ts: new Date(now).toISOString()
  };
};
const broadcast = () => ({ payload: summary() });

// timer: hanya siaran ke dashboard
if (!msg.req) { global.set('qc', S); return [null, broadcast()]; }

const action = msg.req.params.action;
const body = (msg.payload && typeof msg.payload === 'object') ? msg.payload : {};
const reply = (code, payload, bc) => { msg.statusCode = code; msg.payload = payload; global.set('qc', S); return [msg, bc ? broadcast() : null]; };
const fail = (code, errCode, message) => reply(code, { code: errCode, message }, false);

if (action === 'catalog') return reply(200, { station: STATION, operator: OPERATOR, parts: PARTS }, false);
if (action === 'state') return reply(200, summary(), false);

if (action === 'reset') { S = fresh(now); return reply(200, { ok: true }, true); }

const vin = typeof body.vin === 'string' ? body.vin.trim().toUpperCase() : '';
const dev = typeof body.deviceId === 'string' ? body.deviceId.slice(0, 64) : '';

if (action === 'scan') {
  if (!/^[A-Z0-9]{10,20}$/.test(vin) || !dev) return fail(400, 'VIN_INVALID', 'Format VIN tidak valid. Periksa VIN lalu coba lagi.');
  const unit = unitOf(vin);
  if (!unit) return fail(404, 'VIN_NOT_FOUND', 'VIN tidak ditemukan. Periksa VIN dan akses stasiun.');
  if (S.units[vin] === 'finalized') return fail(409, 'ALREADY_FINALIZED', 'VIN ini sudah selesai diperiksa (GOOD).');
  if (S.units[vin] === 'repair') return fail(409, 'REPAIR_REQUIRED', 'VIN ini punya NG dan menunggu repair.');
  const act = S.sessions.find(s => s.vin === vin);
  if (act && act.deviceId !== dev) return fail(409, 'SESSION_ACTIVE', 'Ada sesi aktif untuk VIN ini di tablet lain.');
  S.sessions = S.sessions.filter(s => s.deviceId !== dev);   // satu tablet satu sesi
  S.sessions.push(act || { vin, deviceId: dev, operator: OPERATOR, start: now });
  return reply(200, { unit }, true);
}

if (action === 'cancel') {
  S.sessions = S.sessions.filter(s => !(s.vin === vin && s.deviceId === dev));
  return reply(200, { ok: true }, true);
}

if (action === 'finish') {
  const ses = S.sessions.find(s => s.vin === vin && s.deviceId === dev);
  if (!ses) return fail(409, 'NO_SESSION', 'Sesi inspeksi tidak ditemukan atau sudah berakhir. Scan VIN lagi.');
  if (!Array.isArray(body.ng) || body.ng.length > 60) return fail(400, 'NG_INVALID', 'Data NG tidak valid.');
  const seen = new Set();
  const ng = [];
  for (const g of body.ng) {
    const part = g && typeof g.partId === 'string' ? PARTS.find(p => p.id === g.partId) : null;
    if (!part || typeof g.defect !== 'string' || !part.defects.includes(g.defect)) return fail(400, 'NG_INVALID', 'Defect tidak dikenal untuk part tersebut.');
    const k = g.partId + '|' + g.defect;
    if (!seen.has(k)) { seen.add(k); ng.push({ partId: g.partId, defect: g.defect }); }
  }
  const status = ng.length ? 'NOT_GOOD' : 'GOOD';
  S.results.unshift({ id: now.toString(36), vin, model: unitOf(vin).model, at: now, operator: ses.operator, status, ng, seconds: Math.round((now - ses.start) / 1000) });
  S.results = S.results.slice(0, 300);
  S.units[vin] = status === 'GOOD' ? 'finalized' : 'repair';
  S.sessions = S.sessions.filter(s => s !== ses);
  return reply(200, { vin, status, ng }, true);
}

return fail(404, 'UNKNOWN_ACTION', 'Aksi tidak dikenal.');
